<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Shared\Exception\ConstraintException;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\TrustedClientBackchannelTokenDeliveryModeVO;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\TrustedClientBackchannelTokenDeliveryModeOptions;

final class TrustedClientBackchannelTokenDeliveryModeVOUnitTest extends TestCase
{
    public function test_asignation_keep_value(): void
    {
        $value = TrustedClientBackchannelTokenDeliveryModeOptions::POLL;
        $ref = TrustedClientBackchannelTokenDeliveryModeVO::from($value);
        $this->assertEquals(TrustedClientBackchannelTokenDeliveryModeOptions::POLL, $ref->value());
        $other = TrustedClientBackchannelTokenDeliveryModeVO::tryFrom($ref, new ConstraintFailList());
        $this->assertSame($other, $ref);
        $more = TrustedClientBackchannelTokenDeliveryModeVO::from($ref);
        $this->assertSame($more, $ref);
    }
    public function test_asignation_invalid_type(): void
    {
        $errors = new ConstraintFailList();
        $other = TrustedClientBackchannelTokenDeliveryModeVO::tryFrom('1', $errors);
        $this->assertNull($other);
        $this->assertTrue($errors->hasErrors());
    }
    public function test_optimist_asignation_invalid_type(): void
    {
        $this->expectException(ConstraintException::class);
        $method = new ReflectionMethod(TrustedClientBackchannelTokenDeliveryModeVO::class, 'fromUnsafe');
        $method->invoke(null, [11, "bad"]);
    }
    public function test_equals(): void
    {
        $one = TrustedClientBackchannelTokenDeliveryModeVO::from(TrustedClientBackchannelTokenDeliveryModeOptions::POLL);
        $same = TrustedClientBackchannelTokenDeliveryModeVO::from(TrustedClientBackchannelTokenDeliveryModeOptions::POLL);
        $other = TrustedClientBackchannelTokenDeliveryModeVO::from(TrustedClientBackchannelTokenDeliveryModeOptions::PING);
        $withEmpty = $one->equals(null);
        $withSame = $one->equals($same);
        $withOther = $one->equals($other);

        $this->assertFalse($withEmpty);
        $this->assertTrue($withSame);
        $this->assertFalse($withOther);
    }
    public function test_empty(): void
    {
        $ref = TrustedClientBackchannelTokenDeliveryModeVO::empty();
        $this->assertNull($ref->value());
    }
    public function test_try_from_empty(): void
    {
        $ref = TrustedClientBackchannelTokenDeliveryModeVO::tryFrom(null, new ConstraintFailList());
        $this->assertNull($ref->value());
    }
}
